package gal.rodrigosambade.locationlab; import android.content.*; import android.util.Log; import com.google.android.gms.location.*; public class GeofenceReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){GeofencingEvent e=GeofencingEvent.fromIntent(i);if(e!=null&&!e.hasError())Log.i("GeofenceLab","transition="+e.getGeofenceTransition()+" triggers="+e.getTriggeringGeofences());}}